package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;
import com.lianxibu.site.domain.protocol.*;
import com.lianxibu.site.repository.content.*;
import com.lianxibu.site.repository.jobs.*;
import com.lianxibu.site.service.content.*;
import com.lianxibu.site.service.content.ReviewPublicationService.Receipt;
import org.junit.jupiter.api.*;

class ContentReviewEvidenceServiceTest {
 ResultJdbcStoreTest fixture;FrozenContentVersionService versions;ContentReviewEvidenceService evidence;
 static final String HASH="a".repeat(64);
 @BeforeEach void setup(){fixture=new ResultJdbcStoreTest();fixture.fixture();install();}
 void install(){fixture.apply();versions=new FrozenContentVersionService(new JdbcFrozenContentVersions(fixture.source));evidence=new ContentReviewEvidenceService(fixture.source,new ContentReadService(new JdbcContentReads(fixture.source),fixture.tx,ContentReadService.denyUnverifiedReferences()),versions,fixture.clock,"fictional-owner");}
 ContentVersionKey current(){var row=new JdbcContentReads(fixture.source).current("report","fictional-report");return new ContentVersionKey(row.kind(),row.id(),row.effectiveBodyRevision(),java.util.HexFormat.of().formatHex(row.bodyHashV1()),row.inputJobId());}
 void edit(String body){var row=new JdbcContentReads(fixture.source).current("report","fictional-report");assertNotNull(new GeneratedContentService(new JdbcGeneratedContents(fixture.source),fixture.clock).write(new GeneratedContentService.Write("report","fictional-report",row.revision(),ResultJdbcStoreTest.ROOT,body)));}
 Receipt perform(String key,String body,boolean fail){return fixture.writes.execute(fixture.action(key),k->evidence.committed(k,HASH),a->{edit(body);var version=current();var row=new JdbcContentReads(fixture.source).current("report","fictional-report");var receipt=new Receipt(row.kind(),row.id(),row.revision(),row.state(),null);evidence.append(key,HASH,"Fictional edit",receipt,version);if(fail)throw new IllegalStateException("fictional failure after receipt");return receipt;});}
 @Test void fullUnicodeEditedBodyAndInputRemainProvableAfterAnotherReplacement(){String body=ResultJdbcStoreTest.BODY.replace("Fictional text","😀".repeat(30000));var receipt=perform("fictional-edited-body",body,false);var old=current();var proof=versions.find(old).orElseThrow();assertTrue(proof.bodyJson().contains("😀"));assertEquals(2,old.revision());perform("fictional-next-body",ResultJdbcStoreTest.BODY.replace("Fictional text","Fictional next edit"),false);assertEquals(proof.bodyJson(),versions.find(old).orElseThrow().bodyJson());assertEquals(receipt,evidence.committed("fictional-edited-body",HASH));assertThrows(IllegalStateException.class,()->evidence.committed("fictional-edited-body","b".repeat(64)));assertEquals(1,fixture.sends);}
 @Test void outerFailureRollsBackBodyArchiveAndPermanentReceipt(){assertThrows(RuntimeException.class,()->perform("fictional-edit-rollback",ResultJdbcStoreTest.BODY.replace("Fictional text","Fictional rolled back"),true));assertEquals(1,current().revision());assertEquals(0,fixture.jdbc.queryForObject("SELECT COUNT(*) FROM jobs WHERE target_type IN ('content_review_action','content_review_version')",Integer.class));assertEquals(0,fixture.jdbc.queryForObject("SELECT COUNT(*) FROM jobs WHERE purpose='review'",Integer.class));}
 @Test void committedAckLossReconstructsOriginalReceiptAndDoesNotRepeatEdit(){fixture.tx.ackLost=true;String body=ResultJdbcStoreTest.BODY.replace("Fictional text","Fictional edited once");var result=perform("fictional-unknown-edit",body,false);assertEquals(2,result.revision());assertEquals(result,perform("fictional-unknown-edit",body,false));assertEquals(2,current().revision());assertEquals(1,fixture.jdbc.queryForObject("SELECT COUNT(*) FROM jobs WHERE target_type='content_review_version'",Integer.class));assertEquals(1,fixture.sends);}
 @Test void crossOwnerNonCurrentOrNewCitationCannotBeArchived(){var real=current();assertThrows(IllegalStateException.class,()->fixture.writes.execute(fixture.action("fictional-wrong-version"),k->null,a->evidence.archiveCurrent(new ContentVersionKey(real.contentKind(),real.contentId(),9,real.bodyHash(),real.inputJobId()))));assertThrows(IllegalStateException.class,()->fixture.writes.execute(fixture.action("fictional-wrong-owner"),k->null,a->evidence.archiveCurrent(new ContentVersionKey(real.contentKind(),real.contentId(),real.revision(),real.bodyHash(),"fictional-other-root"))));String body=ResultJdbcStoreTest.BODY.replace("fictional-citation","fictional-unfrozen-citation");assertThrows(IllegalStateException.class,()->perform("fictional-new-citation",body,false));assertEquals(1,current().revision());assertEquals(0,fixture.jdbc.queryForObject("SELECT COUNT(*) FROM jobs WHERE purpose='review'",Integer.class));}
 @Test void archiveOrInputTamperingNeverUsesCurrentRowAsReplacementProof(){perform("fictional-edited-body",ResultJdbcStoreTest.BODY.replace("Fictional text","Fictional saved edit"),false);var key=current();fixture.jdbc.update("UPDATE jobs SET payload_json=? WHERE purpose='review'",ResultJdbcStoreTest.BODY);assertThrows(IllegalStateException.class,()->versions.find(key));assertThrows(RuntimeException.class,()->evidence.committed("fictional-edited-body",HASH));}
}
